import NextAuth, { AuthOptions } from "next-auth";
import GoogleProvider from "next-auth/providers/google";
import CredentialsProvider from "next-auth/providers/credentials";
import { JWT } from "next-auth/jwt";
import { NextApiRequest, NextApiResponse } from "next";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

const authOptions: AuthOptions = {
  providers: [
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "text" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials?: Record<"email" | "password", string>) {
        if (!credentials?.email || !credentials?.password) {
          throw new Error("Missing email or password");
        }

        const res = await fetch(`${BACKEND_URL}/api/v1/auth/login`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(credentials),
        });
        
        if (!res.ok) {
          const errorData = await res.json();
          throw new Error(errorData.message || "Invalid credentials");
        }

        const user = await res.json();
        return {
          id: user.id,
          name: user.name,
          email: user.email,
          accessToken: user.accessToken,
          refreshToken: user.refreshToken,
          role: user.role,
          verified: user.verified,
        };
      },
    }),
    
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      authorization: { params: { scope: "openid email profile" } },
    }),
  ],

  session: {
    strategy: "jwt" as "jwt",
  },

  callbacks: {
    async jwt({ token, account, user }: { token: JWT; account?: any; user?: any }) {
      if (account && account.provider === "google") {
        const googleUserInfo = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
          headers: { Authorization: `Bearer ${account.access_token}` },
        }).then(res => res.json());
        
        const backendRes = await fetch(`${BACKEND_URL}/api/v1/auth/oauth/google`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            email: googleUserInfo.email,
            name: googleUserInfo.name,
            googleId: googleUserInfo.sub,
            profileImage: googleUserInfo.picture,
          }),
        }).catch(err => {
          console.error("OAuth login fetch failed:", err);
          throw new Error("Failed to communicate with backend");
        });
        
        if (!backendRes || !backendRes.ok) {
          throw new Error("OAuth login failed: " + (await backendRes.text()));
        }
        

        const backendUser = await backendRes.json();
        token.accessToken = backendUser.accessToken;
        token.refreshToken = backendUser.refreshToken;
        token.role = backendUser.role;
        token.verified = backendUser.verified;
      }

      if (user) {
        token.accessToken = user.accessToken;
        token.refreshToken = user.refreshToken;
        token.role = user.role;
        token.verified = user.verified;
      }
      return token;
    },
    async session({ session, token }: { session: any; token: JWT }) {
      session.accessToken = token.accessToken;
      session.refreshToken = token.refreshToken;
      session.user = {
        ...session.user,
        role: token.role,
        verified: token.verified,
      };
      return session;
    },
    async redirect({ url, baseUrl }: { url: string; baseUrl: string }) {
      return url.startsWith(baseUrl) ? url : `${baseUrl}/dashboard/user`;
    },
  },
  secret: process.env.NEXTAUTH_SECRET,
  pages: { signIn: "/auth/login" },
};

const handler = (req: NextApiRequest, res: NextApiResponse) =>
  NextAuth(req, res, { ...authOptions, trustHost: true });

export { handler as GET, handler as POST };

